using Commerce;

namespace ShoppingCart.Tests;

[TestClass]
public class ShoppingCartTests
{
    private Commerce.ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup() => _cart = new Commerce.ShoppingCart();

    // --- AddItem tests ---

    [TestMethod]
    public void AddItem_SingleItem_IncreasesTotal()
    {
        _cart.AddItem("SKU-001", 9.99m, 1);

        Assert.AreEqual(9.99m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_MultipleQuantity_MultipliesPrice()
    {
        _cart.AddItem("SKU-001", 5.00m, 3);

        Assert.AreEqual(15.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_MultipleDistinctItems_SumsAll()
    {
        _cart.AddItem("SKU-001", 10.00m, 1);
        _cart.AddItem("SKU-002", 20.00m, 2);

        Assert.AreEqual(50.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_DuplicateSku_AddsAsSeparateEntry()
    {
        _cart.AddItem("SKU-001", 10.00m, 1);
        _cart.AddItem("SKU-001", 10.00m, 1);

        Assert.AreEqual(20.00m, _cart.GetTotal());
    }

    // --- RemoveItem tests ---

    [TestMethod]
    public void RemoveItem_ExistingSku_ReturnsTrueAndReducesTotal()
    {
        _cart.AddItem("SKU-001", 10.00m, 2);
        _cart.AddItem("SKU-002", 5.00m, 1);

        bool removed = _cart.RemoveItem("SKU-001");

        Assert.IsTrue(removed);
        Assert.AreEqual(5.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void RemoveItem_NonExistingSku_ReturnsFalse()
    {
        _cart.AddItem("SKU-001", 10.00m, 1);

        bool removed = _cart.RemoveItem("SKU-999");

        Assert.IsFalse(removed);
    }

    [TestMethod]
    public void RemoveItem_DuplicateSkus_RemovesAll()
    {
        _cart.AddItem("SKU-001", 10.00m, 1);
        _cart.AddItem("SKU-001", 10.00m, 2);

        _cart.RemoveItem("SKU-001");

        Assert.AreEqual(0m, _cart.GetTotal());
    }

    [TestMethod]
    public void RemoveItem_EmptyCart_ReturnsFalse()
    {
        bool removed = _cart.RemoveItem("SKU-001");

        Assert.IsFalse(removed);
    }

    // --- GetTotal tests ---

    [TestMethod]
    public void GetTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _cart.GetTotal());
    }

    [TestMethod]
    public void GetTotal_AfterAddAndRemove_ReflectsCurrentState()
    {
        _cart.AddItem("SKU-001", 25.00m, 2);
        _cart.AddItem("SKU-002", 10.00m, 1);
        _cart.RemoveItem("SKU-001");

        Assert.AreEqual(10.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void GetTotal_HighPrecisionDecimals_IsAccurate()
    {
        _cart.AddItem("SKU-001", 1.01m, 3);

        Assert.AreEqual(3.03m, _cart.GetTotal());
    }
}

